changeSet.sql:

create or alter function [graph].[GetPathByAssetId]
(
	@id bigint,
	@levelDelimiter nvarchar(50),
	@keyDelimiter nvarchar(50)
)
returns nvarchar(850)
as
begin
	declare @segments xml
	select @segments = Segments from AssetPath where ID = @id;
	return dbo.GetDisplayPath(@segments, @levelDelimiter, @keyDelimiter)
end

changeSet.rollback:

create or alter function [graph].[GetPathByAssetId]
(
	@id bigint,
	@levelDelimiter nvarchar(50),
	@keyDelimiter nvarchar(50)
)
returns nvarchar(850)
as
begin
	declare @segments xml
	select @segments = Segments from graph.AssetNode where ID = @id;
	return graph.GetPath(@segments, @levelDelimiter, @keyDelimiter)
end
